I'm building a single-page Pomodoro timer with start/pause/reset, automatic 25/5 minute alternation, and a daily work-session counter stored in localStorage.

<file path="index.html">
<!DOCTYPE html>
<html lang="en" data-mode="work">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pomodoro Timer</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <main class="app" id="app">
    <p class="mode-label" id="mode-label" aria-live="polite">Work session</p>

    <div class="timer" id="timer" role="timer" aria-label="Time remaining">25:00</div>

    <div class="controls">
      <button id="toggle-btn" class="btn btn-primary" type="button">Start</button>
      <button id="reset-btn" class="btn btn-secondary" type="button">Reset</button>
    </div>

    <section class="counter" aria-labelledby="counter-label">
      <span class="counter-label" id="counter-label">Work sessions completed today</span>
      <strong class="counter-value" id="count">0</strong>
    </section>
  </main>
  <script src="app.js"></script>
</body>
</html>
